package optimizer

import "testing"

// TestPyNum checks the int/Decimal port against CPython 3.14: each row is a, b, and str() of
// a+b, a-b, a*b and a/b (empty when both are ints, which simplify never divides), generated by
// running the same operations on int(text) or Decimal(text).
func TestPyNum(t *testing.T) {
	for _, tc := range []struct{ a, b, add, sub, mul, div string }{
		{"1", "2", "3", "-1", "2", ""},
		{"1.5", "2", "3.5", "-0.5", "3.0", "0.75"},
		{"0.1", "0.2", "0.3", "-0.1", "0.02", "0.5"},
		{"1.50", "2", "3.50", "-0.50", "3.00", "0.75"},
		{"10", "3", "13", "7", "30", ""},
		{"1", "3.0", "4.0", "-2.0", "3.0", "0.3333333333333333333333333333"},
		{"2.0", "3", "5.0", "-1.0", "6.0", "0.6666666666666666666666666667"},
		{"1e3", "2", "1002", "998", "2E+3", "5E+2"},
		{"2.5e-3", "4", "4.0025", "-3.9975", "0.0100", "0.000625"},
		{"0.00", "1", "1.00", "-1.00", "0.00", "0.00"},
		{"100", "0.5", "100.5", "99.5", "50.0", "2.0E+2"},
		{"-4", "1.5", "-2.5", "-5.5", "-6.0", "-2.666666666666666666666666667"},
		{"12345678901234567890123456789", "2.5", "1.234567890123456789012345679E+28", "1.234567890123456789012345679E+28", "3.086419725308641972530864197E+28", "4938271560493827156049382716"},
		{"1_000", "1", "1001", "999", "1000", ""},
		{"7", "0.1", "7.1", "6.9", "0.7", "7E+1"},
		{"1", "1.0", "2.0", "0.0", "1.0", "1"},
		{"0.5", "0.5", "1.0", "0.0", "0.25", "1"},
	} {
		a, ok1 := parsePyNum(tc.a)
		b, ok2 := parsePyNum(tc.b)
		if !ok1 || !ok2 {
			t.Fatalf("parse %q / %q failed", tc.a, tc.b)
		}
		check := func(op, got, want string) {
			if got != want {
				t.Errorf("%s %s %s = %s, want %s", tc.a, op, tc.b, got, want)
			}
		}
		check("+", a.add(b).String(), tc.add)
		check("-", a.sub(b).String(), tc.sub)
		check("*", a.mul(b).String(), tc.mul)
		if tc.div != "" {
			q, _ := a.div(b)
			check("/", q.String(), tc.div)
		}
	}
}
